const fs = require('fs');
const path = require('path');

const overflowPath = path.join('/data', 'arxiv_overflow.json');
let overflowBuffer = [];

// 1. Load papers from overflow
if (fs.existsSync(overflowPath)) {
  try {
    overflowBuffer = JSON.parse(fs.readFileSync(overflowPath, 'utf8') || '[]');
  } catch (e) {
    console.error("Error reading overflow file:", e);
    overflowBuffer = [];
  }
}

// 2. Clear the overflow file completely
try {
  fs.writeFileSync(overflowPath, JSON.stringify([], null, 2), 'utf8');
} catch (err) {
  console.error("Failed to clear overflow buffer:", err);
}

// 3. If no papers were found, stop execution cleanly
if (!Array.isArray(overflowBuffer) || overflowBuffer.length === 0) {
  return [];
}

// 4. Output each paper as an item for downstream podcast processing
return overflowBuffer.map(paper => {
  const id = paper.arxivId || paper.arxiv_id;
  return {
    json: {
      arxivId: id,
      arxiv_id: id,
      url: paper.url || (id ? `https://arxiv.org/abs/${id}` : "#"),
      debugTitle: paper.title || paper.debugTitle || "Untitled Overflow Paper",
      authors: paper.authors || ""
    }
  };
});

// 'Generate Briefing' continues on error, so one failing paper no longer stops the papers after it.
// Raise a single error after the loop so the Error Workflow still reports what failed.
const done = $input.all();
const failed = done.filter(i => i.json && i.json.error);
if (failed.length === 0) return done;
const describe = (e) => String(typeof e === 'string' ? e : ((e && e.message) || JSON.stringify(e))).slice(0, 200);
const ids = failed.map(i => i.json.arxivId || i.json.arxivID || 'unknown');
throw new Error(`Briefing failed for ${failed.length} of ${done.length} papers (${ids.join(', ')}); the others were processed. First error: ${describe(failed[0].json.error)}`);
